// Cerid GREASE values reserved by cerid.negotiation: never assigned, sent by every build so that peers which
// refuse unknown values fail in testing (RFC 8701 practice).
inline constexpr u16 kGreaseIds[] = {
    0x0A0AU, 0x1A1AU, 0x2A2AU, 0x3A3AU, 0x4A4AU, 0x5A5AU, 0x6A6AU, 0x7A7AU,
    0x8A8AU, 0x9A9AU, 0xAAAAU, 0xBABAU, 0xCACAU, 0xDADAU, 0xEAEAU, 0xFAFAU,
};

// Whether `value` is one of kGreaseIds: the fixed digits of 0x?A?A and the same digit in every `?`.
[[nodiscard]] constexpr bool is_grease(u16 value) noexcept
{
    return (value & 0x0F0FU) == 0x0A0AU &&
           ((value >> 12U) & 0x0FU) == ((value >> 4U) & 0x0FU);
}

